import os
import requests

def conditional_update(payload, config=None):
    config = config or {}
    endpoint = config.get('endpoint', 'https://api.example.com/documents')
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {config.get("api_key")}'
    }
    url = f'{endpoint}/{payload["id"]}'
    data = {
        'if_match': payload['version'],
        'data': payload['data']
    }
    response = requests.put(url, headers=headers, json=data)
    result = response.json()
    return result

